[meta]
name = Herran's Castle
ambient = 0.36 0.36 0.44
fog = 0.1 0.1 0.13
fog_range = 16 220
model_range = 60
indoor_range = 26
sky = storm
atlas = herrans_castle
torch = 6 1.0 0.72 0.45
start = 19 81 -90
default = w
entity_floor = auto
roofs = true
edge_top = 24
edge_tex = mountain_rock

// Herran's Castle, built against the flank of the Hollow Peak, the black mountain behind Vesperholm,
// in a storm that never breaks. Lyra's portal opens on a ledge of the mountain below it, the Portal
// Ledge, where a shrine stands. North of it the Long Causeway runs out over the gorge, between statues
// and the household's grafted footmen, to the platform before the barbican; its great gate is sealed,
// bound to the two Castellan Wardens on the decks of the towers either side of it (`door seal=gate`,
// `world/seals.py`: lifts climb both towers, and with both Wardens slain the gate opens for good).
// Past it, the Outer Ward and its shrine under the many towers; the Great Hall, vast and dark, and its
// east chapel; west of it, up a short stair, the Hall of Sentinels, where two stone giants of the peak
// keep the way (`door boss=sentinels_dead`, a rear door onto the keep stair). The keep stair climbs to
// Herran's library at 8 m, where a false wall behind the shelves hides the way down into the mountain,
// to his laboratory (`herran_laboratory`); on to his study at 10 m and its shrine, and through his
// door the anatomy theatre, caged under its broken iron dome and open to the storm through its
// breach, where Herran, the Many-Handed, rises before his door with the Auric Sigil.

[legend]
// The gorge: a sheer drop into the dark that no one lives through.
_ = floor tex=mountain_rock h=-40 side=mountain_rock chasm fall=gorge
// The mountain's rock, round the ledge.
m = wall tex=mountain_rock top=24 cap=mountain_rock
// The Portal Ledge.
l = floor tex=mountain_rock h=0 side=mountain_rock
// The causeway, the platform at its head and their low parapets.
c = floor tex=castle_flags h=0 side=castle_stone
p = wall tex=castle_stone top=1.2 cap=castle_stone
// The castle's walls, and the keep's, taller, split by the storm and the years down their faces open to
// the sky (the ward's, the barbican's over the platform and the gorge, the keep's over the theatre).
# = wall tex=castle_stone top=14 cap=castle_slate dress=cracks
% = wall tex=castle_stone top=22 cap=castle_slate dress=cracks
// The barbican: a tower's room, its lift's shaft, its deck at 8 m inside its crenels; the gate passage.
t = floor tex=castle_flags h=0 ceil=6 ceil_tex=castle_stone side=castle_stone roof=14 dark=0.4
q = floor tex=castle_flags h=0 ceil=12.5 ceil_tex=castle_stone side=castle_stone roof=14 chasm
d = floor tex=castle_flags h=8 side=castle_stone
k = wall tex=castle_stone top=9.2 cap=castle_stone
g = floor tex=castle_flags h=0 ceil=5 ceil_tex=castle_stone side=castle_stone roof=14 dark=0.35
// The Outer Ward, open to the storm.
w = floor tex=castle_flags h=0 side=castle_stone
// The Great Hall's arch from the ward, the hall, and its east chapel.
a = floor tex=castle_flags h=0 ceil=6 ceil_tex=castle_stone side=castle_stone roof=14 dark=0.35
h = floor tex=castle_flags h=0 ceil=12 ceil_tex=castle_stone side=castle_stone roof=14 dark=0.45
u = floor tex=castle_flags h=0 ceil=6 ceil_tex=castle_stone side=castle_stone roof=14 dark=0.5
// The short stair up to the Hall of Sentinels, the floor under its doors, and the hall.
1 = floor tex=castle_flags h=0.5 ceil=5 ceil_tex=castle_stone side=castle_stone roof=14 dark=0.4
2 = floor tex=castle_flags h=1 ceil=5.5 ceil_tex=castle_stone side=castle_stone roof=14 dark=0.4
3 = floor tex=castle_flags h=1.5 ceil=6 ceil_tex=castle_stone side=castle_stone roof=14 dark=0.4
v = floor tex=castle_flags h=2 ceil=6 ceil_tex=castle_stone side=castle_stone roof=14 dark=0.4
s = floor tex=castle_flags h=2 ceil=13 ceil_tex=castle_stone side=castle_stone roof=14 dark=0.4
// The keep stair, half a metre a tile, each step under its own vault.
α = floor tex=castle_flags h=2.5 ceil=7 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.5
β = floor tex=castle_flags h=3 ceil=7.5 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.5
γ = floor tex=castle_flags h=3.5 ceil=8 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.5
δ = floor tex=castle_flags h=4 ceil=8.5 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.5
ε = floor tex=castle_flags h=4.5 ceil=9 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.5
ζ = floor tex=castle_flags h=5 ceil=9.5 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.5
η = floor tex=castle_flags h=5.5 ceil=10 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.5
θ = floor tex=castle_flags h=6 ceil=10.5 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.5
ι = floor tex=castle_flags h=6.5 ceil=11 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.5
κ = floor tex=castle_flags h=7 ceil=11.5 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.5
λ = floor tex=castle_flags h=7.5 ceil=12 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.5
// The library, 8 m up, and the hidden way down behind its false wall, darker still.
b = floor tex=castle_flags h=8 ceil=13 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.4
x = floor tex=lab_floor h=8 ceil=11 ceil_tex=lab_stone side=lab_stone roof=22 dark=0.7
// The stair on to the study, the study at 10 m, and the floor under Herran's door.
ν = floor tex=castle_flags h=8.5 ceil=12.5 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.45
ξ = floor tex=castle_flags h=9 ceil=13 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.45
ο = floor tex=castle_flags h=9.5 ceil=13.5 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.45
y = floor tex=castle_flags h=10 ceil=14.5 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.3
z = floor tex=castle_flags h=10 ceil=14 ceil_tex=castle_stone side=castle_stone roof=22 dark=0.3
// The anatomy theatre, open to the storm, ringed by its parapet (wall, never chasm: an arena's flood
// would leak into a chasm).
o = floor tex=castle_flags h=10 side=castle_stone
e = wall tex=castle_stone top=11.2 cap=castle_stone

