[entities]
// The portal back to Lyra's Chapel in Vesperholm, at the ledge's south edge, facing the ledge; the
// shrines: on the ledge, in the Outer Ward past the gate, and in Herran's study.
A = exit map=vesperholm at=21,3,90 label=Step_through_the_portal model=argent_portal yaw=-90 on=l
B = save_statue
// Light: a cold light on the ledge and in the barbican's rooms, high in the Great Hall and up the keep
// stair; the household's fire-baskets, each an iron hand cupping its fire, along the causeway, before
// the barbican, on its towers' decks and in the ward; candelabra in the halls and the library; a warm
// light in the library and the study, where Herran works by candle against the storm; and torches
// held out from the walls in iron hands (`torch model=castle`) by every door and up the keep stair.
N = light y=4 color=0.9,0.8,0.7 radius=9
Ñ = light y=3 color=0.9,0.75,0.6 radius=7 on=γ
Ò = light y=3 color=0.9,0.75,0.6 radius=7 on=θ
F = brazier model=castle
K = candelabra
и = light y=3.2 color=1.0,0.62,0.34 radius=8
Б = torch model=castle
л = torch model=castle on=ζ
п = torch model=castle on=β
// Statues along the causeway and in the ward; the Great Hall's pillars.
T = gate_statue
P = pillar
// Herran's household, and the barbican's sealed gate with the two Wardens bound to it, one on the
// deck of each tower, up its lift.
G = grafted_footman
D = door seal=gate model=sealed on=g
L = lift top=8 model=cage on=q
W = castellan_warden seal=gate
// The Hall of Sentinels: its great door from the Great Hall's stair, its rear door onto the keep
// stair, and its two stone giants, each with a piece of its armour to drop.
O = door boss=sentinels_dead on=v
Q = door boss=sentinels_dead rear on=v
U = bulwark_sentinel item=sentinel_plate
V = blade_sentinel item=sentinel_gauntlets
// The library's bookcases, the false wall behind them and the hidden stair down into the mountain.
Ë = bookcase
X = secret_wall on=x
E = exit map=herran_laboratory at=16,2,90 label=Descend_into_the_dark model=sunken_stair yaw=-90 on=x
// Herran's study: his dissecting table; his door, and Herran in his theatre, risen before it and
// facing it, under the iron cage-dome over the whole of the theatre (`span=` tiles from its -X/-Z floor
// tile, against the keep on its west side), with his telescope in the far corner, trained on the storm.
Í = dissecting_table
Z = door boss=herran_dead on=z
H = herran yaw=180
Y = anatomy_dome span=12,10 walled=w spring=4.8 rise=6 on=o
Ô = telescope yaw=-45 on=o
// Finds, in the household's own chests (`model=anatomist`): Hearth Ash in the ward, Mender's Kits in
// the chapel, a draught and tonics on the towers' decks and in the library.
É = chest item=hearth_ash count=2 gold=90 model=anatomist
Ê = chest item=menders_kit count=2 gold=140 model=anatomist
Ç = chest item=ember_draught count=2 gold=120 model=anatomist
È = chest item=red_tonic count=3 gold=120 model=anatomist
Ì = chest item=red_tonic count=3 gold=300 model=anatomist
// Two pages of Herran's journal.
I = hint text="The sentinels keep the stair, and the stair keeps me.|Below, in the rock, I keep what I have made."
J = hint text="Mother has a hundred hands to hold us. I have eight.|It will be enough. It must be enough."
// The skyline: the Hollow Peak beyond the keep, and the castle's towers.
M = hollow_peak height=140 width=120 yaw=-90 on=%
À = castle_tower style=keep height=40 width=8 on=%
Á = castle_tower style=round height=30 on=%
Â = castle_tower style=octagon height=28 on=%
Ã = castle_tower style=belfry height=32 on=%
Ä = castle_tower style=square height=30 on=#
Å = castle_tower style=round height=26 on=#
Æ = castle_tower style=square height=27 on=#
Î = castle_tower style=octagon height=24 on=#
// The great walls' faces open to the storm, dressed down from their heads: buttresses stepping back
// up them, a gargoyle spouting from each and a pinnacle over the wall, with string courses, a plinth and
// a corbel table along them (`span=` metres): round the Outer Ward, facing in, and across the
// barbican's face over the platform, between its doors (`yaw=` out of the face).
Г = castle_buttress yaw=90 span=8 on=#
Д = castle_buttress yaw=-90 span=8 on=#
Ж = castle_buttress yaw=0 span=8 on=#
З = castle_buttress yaw=180 span=8 on=#
Ђ = castle_buttress yaw=90 span=4 on=#
// Windows: twin lancets lit by candles high in the ward's walls and the barbican's face, arrow loops
// low beside its gate and the ward's, and in the halls, the chapel and the study lancets lit cold by
// the storm (`rise=` the sill's height).
И = castle_window style=twin light=candle rise=7
Л = castle_window style=loop light=dark rise=3.6
П = castle_window style=lancet light=storm rise=7.5
Ф = castle_window style=lancet light=storm rise=2.6
// Herran's banners, the open hand with the sun in its palm: great ones either side of the barbican's
// gate and the hall's arch and across the Great Hall's north wall, smaller ones in the theatre either
// side of his door; tapestries of the Many-Handed down the Great Hall, the Hall of Sentinels and the
// chapel; and his standards on the parapets of the causeway and the platform.
Ц = hand_banner rise=10 length=7
Ч = hand_banner rise=9 length=5.5
Ы = hand_banner rise=4.4 length=2.8
Щ = hand_banner style=tapestry rise=7 length=4.4
Ъ = hand_banner style=tapestry rise=4.6 length=3
Ь = hand_standard yaw=90 on=p
// The anatomist's household: his charts and shelves of specimens in the chapel, the library and the
// study; surgical trolleys; his failures hung up on hooks in the chapel and the study and in gibbet
// cages on the ward's walls; chains in the barbican's rooms and the study.
Э = anatomy_chart
Ю = specimen_jars
Я = surgical_trolley
б = hung_cadaver style=hook
г = hung_cadaver style=cage
з = wall_chains
// What the years and the storm have broken: statues fallen in the ward and on the Portal Ledge, and
// rubble from the dome's breach in the theatre's north-east quarter (and on the ledge, and in the ward).
д = broken_statue
ж = breach_rubble
// High-backed stone settles against the walls of the Great Hall, the library and the ward, each carved
// with the open hand: one with its velvet cushion still on it, one with a candle burnt down beside a
// book, one broken at the corner (by tile).
ш = castle_bench yaw=0
щ = castle_bench yaw=180
